{
  "ok": false,
  "name": "find_entities",
  "error": {
    "type": "invalid_params",
    "message": "\"{kind: 'offset', offset: 10}\" is not of type 'object'",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "space to search (default 'model')"
        },
        "layer": {
          "description": "layer name, or a list of them"
        },
        "type": {
          "description": "line|polyline|arc|circle|text|blockref|table|dimension|point|hatch, or a list"
        },
        "anchor": {
          "type": "object",
          "description": "match the design anchor: any of alignment, kind (element|offset|station|tick|pc|pt|...), ref, offset. Each takes one value or a list, so {kind: 'offset', offset: [-15, 15]} finds both pavement edges."
        },
        "content_contains": {
          "type": "string",
          "minLength": 1,
          "description": "text entities whose content contains this (case-insensitive)"
        },
        "bounds": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 4,
          "maxItems": 4,
          "description": "[minx, miny, maxx, maxy]"
        },
        "visible_on": {
          "type": "string",
          "minLength": 1,
          "description": "sheet name: keep only model entities that sheet's viewports actually show. Each row then also carries sheet_point -- the middle of the part shown, in paper inches -- and the viewport it is seen through"
        },
        "include_references": {
          "type": "boolean",
          "description": "search attachments too (default true)"
        },
        "detail": {
          "type": "string",
          "enum": [
            "summary",
            "full"
          ],
          "description": "summary (default) is id, type, layer, a point on the entity, its length and anchor; full adds the whole entity"
        },
        "limit": {
          "type": "integer",
          "minimum": 1,
          "maximum": 500,
          "description": "rows to return (default 50)"
        },
        "start": {
          "type": "integer",
          "minimum": 0,
          "description": "skip this many matches (paging)"
        }
      },
      "required": [],
      "additionalProperties": false
    },
    "example": {
      "anchor": {
        "kind": "offset",
        "offset": [
          -15,
          15
        ]
      },
      "visible_on": "P-202"
    }
  }
}

