[tool error]
{
  "ok": false,
  "name": "label_segments",
  "error": {
    "type": "invalid_params",
    "message": "'labels' is not one of ['values', 'tags'] (at 'style')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "description": "lines, polylines (each segment) and arcs to label -- right of way, easements, a deed's courses"
        },
        "style": {
          "type": "string",
          "enum": [
            "values",
            "tags"
          ],
          "description": "values (default): bearing over distance along each line, radius and delta over length on each curve. tags: L1, C1 ... on the linework with a line table and a curve table listing the values"
        },
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "where the labels go (default where the linework is); a sheet letters model linework through its viewports, in paper inches"
        },
        "table": {
          "type": "object",
          "properties": {
            "position": {
              "type": "array",
              "items": {
                "type": "number"
              },
              "minItems": 2,
              "maxItems": 2,
              "description": "top-left corner of the tables"
            },
            "space": {
              "type": "string",
              "minLength": 1,
              "description": "default where the tags go"
            },
            "text_height": {
              "type": "number",
              "exclusiveMinimum": 0
            }
          },
          "required": [
            "position"
          ],
          "additionalProperties": false
        },
        "text_height": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "label height (default 0.10 in on paper)"
        },
        "offset": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "gap between the line and its labels (default 0.6 x the text height)"
        },
        "precision": {
          "type": "integer",
          "minimum": 0,
          "maximum": 6
        },
        "order_along": {
          "type": "string",
          "minLength": 1,
          "description": "number and letter the segments in order of station along this alignment ('RTE-7', or a referenced 'BASE:RTE-7') instead of the order of ids"
        },
        "line_start": {
          "type": "integer",
          "minimum": 1,
          "description": "first line tag number (default 1)"
        },
        "curve_start": {
          "type": "integer",
          "minimum": 1,
          "description": "first curve tag number (default 1)"
        },
        "text_style": {
          "type": "string",
          "minLength": 1
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        }
      },
      "required": [
        "ids"
      ],
      "additionalProperties": false
    },
    "example": {
      "ids": [
        "PL-004"
      ],
      "style": "tags",
      "table": {
        "position": [
          5600.0,
          7700.0
        ]
      },
      "layer": "V-ANNO-ROW"
    }
  },
  "warnings": []
}

